        self.n = n
        self.p = ctypes.c_void_p()
        gsl.gsl_permutation_alloc(ctypes.byref(self.p), n)

    def __del__(self):
        gsl.gsl_permutation_free(self.p)

    def write(self, filename):
        with open(filename, 'wb') as f:
            gsl.gsl_permutation_fwrite(f.fileno(), self.p)

    def read(self, filename):
        with open(filename, 'rb') as f:
            gsl.gsl_permutation_fread(f.fileno(), self.p)

    def get(self):
        p = (ctypes.c_size_t * self.n)()
        gsl.gsl_permutation_unpack(self.p, p)
        return [int(x) for x in p]


