class GSLVector:
    def __init__(self, size):
        self.vector = gsl.gsl_vector_alloc(size)

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

    def copy(self, other):
        gsl.gsl_vector_memcpy(self.vector, other.vector)

    def to_list(self):
        size = gsl.gsl_vector_size(self.vector)
        data = (ctypes.c_double * size).from_address(ctypes.addressof(self.vector.contents.data.contents))
        return list(data)


def copy_gsl_vector(source_list, destination_list):
    source_vector = GSLVector(len(source_list))
    destination_vector = GSLVector(len(destination_list))
    for i in range(len(source_list)):
        source_vector.vector.contents.data[i] = ctypes.c_double(source_list[i])
    for i in range(len(destination_list)):
        destination_vector.vector.contents.data[i] = ctypes.c_double(destination_list[i])
    source_vector.copy(destination_vector)
    return destination_vector.to_list()

