# Convert a numpy matrix to a GSL matrix
def matrix_to_gsl(matrix):
    n = len(matrix)
    gsl_matrix = gsl.gsl_matrix_alloc(n, n)
    for i in range(n):
        for j in range(n):
            gsl.gsl_matrix_set(gsl_matrix, i, j, matrix[i][j])
    return gsl_matrix

# Convert a GSL matrix to a numpy matrix
def gsl_matrix_to_numpy(gsl_matrix):
    n = gsl.gsl_matrix_size(gsl_matrix, 0)
    matrix = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            matrix[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
    return matrix

# Compute the matrix exponential using GSL
def compute_matrix_exponential(gsl_matrix, mode):
    gsl_exponential = gsl.gsl_linalg_exponential_ss
    gsl_exponential.restype = ctypes.POINTER(gsl.gsl_matrix)
    gsl_exponential.argtypes = [ctypes.POINTER(gsl.gsl_matrix), ctypes.c_int]
    exponential = gsl_exponential(gsl_matrix, mode)
    return gsl_matrix_to_numpy(exponential)

