class GSLVector:
    def __init__(self, data):
        self.vector = gsl.gsl_vector_alloc(len(data))
        for i, value in enumerate(data):
            gsl.gsl_vector_set(self.vector, i, value)

    def __del__(self):
        gsl.gsl_vector_free(self.vector)


class GSLMatrix:
    def __init__(self, data):
        self.matrix = gsl.gsl_matrix_alloc(len(data), len(data[0]))
        for i, row in enumerate(data):
            for j, value in enumerate(row):
                gsl.gsl_matrix_set(self.matrix, i, j, value)

    def __del__(self):
        gsl.gsl_matrix_free(self.matrix)


def sort_eigenvalues_eigenvectors(eigenvalues, eigenvectors, sort_type):
    eigenvalues = GSLVector(eigenvalues)
    eigenvectors = GSLMatrix(eigenvectors)

    # Call the gsl_eigen_symmv_sort function
    gsl.gsl_eigen_symmv_sort(eigenvalues.vector, eigenvectors.matrix, sort_type)

    # Get the sorted eigenvalues and eigenvectors
    sorted_eigenvalues = [gsl.gsl_vector_get(eigenvalues.vector, i) for i in range(len(eigenvalues))]
    sorted_eigenvectors = [[gsl.gsl_matrix_get(eigenvectors.matrix, i, j) for j in range(len(eigenvectors))] for i in range(len(eigenvectors))]

    return sorted_eigenvalues, sorted_eigenvectors

