class GSLVector:
    def __init__(self, size):
        self.vector = (ctypes.c_double * size)()
        self.size = size

    def set_value(self, index, value):
        self.vector[index] = value

    def get_value(self, index):
        return self.vector[index]


class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = (ctypes.c_double * (rows * cols))()
        self.rows = rows
        self.cols = cols

    def set_value(self, row, col, value):
        index = row * self.cols + col
        self.matrix[index] = value

    def get_value(self, row, col):
        index = row * self.cols + col
        return self.matrix[index]


def sort_eigenvalues_eigenvectors(eigenvalues, eigenvectors, sort_type):
    # Convert eigenvalues and eigenvectors to GSLVector and GSLMatrix
    gsl_eigenvalues = GSLVector(len(eigenvalues))
    gsl_eigenvectors = GSLMatrix(len(eigenvectors), len(eigenvectors[0]))

    for i in range(len(eigenvalues)):
        gsl_eigenvalues.set_value(i, eigenvalues[i])

    for i in range(len(eigenvectors)):
        for j in range(len(eigenvectors[0])):
            gsl_eigenvectors.set_value(i, j, eigenvectors[i][j])

    # Call the gsl_eigen_symmv_sort function
    gsl.gsl_eigen_symmv_sort(gsl_eigenvalues.vector, gsl_eigenvectors.matrix, sort_type)

    # Convert the sorted eigenvalues and eigenvectors back to Python lists
    sorted_eigenvalues = [gsl_eigenvalues.get_value(i) for i in range(len(eigenvalues))]
    sorted_eigenvectors = [[gsl_eigenvectors.get_value(i, j) for j in range(len(eigenvectors[0]))] for i in range(len(eigenvectors))]

    return sorted_eigenvalues, sorted_eigenvectors

