def list_to_gsl_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    gsl_matrix = gsl.gsl_matrix_calloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set_complex(gsl_matrix, i, j, matrix[i][j])
    return gsl_matrix

