    gsl.gsl_blas_zgemm(ctypes.c_char_p(b'N'), ctypes.c_char_p(b'N'), ctypes.c_double(1.0), matrix_a.gsl_matrix, matrix_b.gsl_matrix, ctypes.c_double(0.0), result)
