def bspline_wlssolve(x, y, weights):
    if len(x) != len(y):
        raise ValueError('x and y must have the same length')
    if weights is not None and len(x) != len(weights):
        raise ValueError('x and weights must have the same length')
    n = len(x)
    k = 4
    nbreak = n - k + 2
    w = gsl_bspline_workspace(nbreak, k)
    B = gsl_vector(n)
    c = gsl_vector(nbreak * (k - 1))
    A = gsl_matrix(n, nbreak * (k - 1))
    rhs = gsl_vector(n)
    for i in range(n):
        w.eval(x[i], B)
        for j in range(nbreak * (k - 1)):
            A.set(i, j, B.get(j))
        rhs.set(i, y[i])
    if weights is not None:
        for i in range(n):
            A.set(i, i, A.get(i, i) * weights[i])
            rhs.set(i, rhs.get(i) * weights[i])
    gsl.gsl_blas_dgemv(ctypes.c_char_p(b'N'), ctypes.c_double(1.0), A, rhs, ctypes.c_double(0.0), c)
    chi_squared = 0.0
    for i in range(n):
        w.eval(x[i], B)
        y_fit = 0.0
        for j in range(nbreak * (k - 1)):
            y_fit += c.get(j) * B.get(j)
        chi_squared += (y[i] - y_fit) ** 2
    return c, chi_squared

