class GSLSpMatrix:
    def __init__(self, size, nnz):
        self.size = size
        self.nnz = nnz
        self.matrix = gsl.gsl_spmatrix_alloc(size, size, nnz, gsl.gsl_spmatrix_csr)

    def populate(self, data):
        for i, row in enumerate(data):
            for j, value in enumerate(row):
                if value != 0:
                    gsl.gsl_spmatrix_set(self.matrix, i, j, value)

    def copy(self, dest):
        gsl.gsl_spmatrix_memcpy(dest.matrix, self.matrix)

