        A.set(i, i, A_data[i])
        r.set(i, b[i])

    for i in range(n):
        x.set(i, 0)

    status = gsl.gsl_gmres_iterate(A.matrix, r.vector, x.vector, tol)

    return [x.get(i) for i in range(n)]

